func TestActualPillowLegacyFormats(t *testing.T) {
	var cases []struct {
		Name      string
		Encoded   string `json:"encoded_base64"`
		Mode      string `json:"loaded_mode"`
		Size      [2]int `json:"loaded_size"`
		LoadedSHA string `json:"loaded_sha256"`
		Gray      []byte `json:"gray100"`
		Hash      string `json:"original_100bit_hash"`
	}
	if err := json.Unmarshal([]byte(sourceCases), &cases); err != nil {
		t.Fatal(err)
	}
	for _, c := range cases {
		t.Run(c.Name, func(t *testing.T) {
			b, err := base64.StdEncoding.DecodeString(c.Encoded)
			if err != nil {
				t.Fatal(err)
			}
			checked := 0
			r, ok, err := legacycodec.Decode(b, func(w, h int) error {
				checked++
				if w < 1 || h < 1 {
					return errors.New("invalid size")
				}
				return nil
			})
			if err != nil {
				t.Fatal(err)
			}
			if !ok {
				t.Fatal("not recognized")
			}
			if checked == 0 {
				t.Fatal("decoded without caller size check")
			}
			if r.Mode != c.Mode || r.Width != c.Size[0] || r.Height != c.Size[1] {
				t.Fatalf("mode/dimensions got %s %dx%d want %s %v", r.Mode, r.Width, r.Height, c.Mode, c.Size)
			}
			if got := fmt.Sprintf("%x", sha256.Sum256(r.Pixels)); got != c.LoadedSHA {
				t.Errorf("loaded bytes SHA got %s want original %s", got, c.LoadedSHA)
			}
			rr := imagehash.Raster{Mode: r.Mode, Width: r.Width, Height: r.Height, Pixels: r.Pixels, Palette: r.Palette}
			gray, err := imagehash.Gray(rr, [2]int{10, 10})
			if err != nil {
				t.Fatal(err)
			}
			if !bytes.Equal(gray, c.Gray) {
				t.Errorf("gray got %v want original %v", gray, c.Gray)
			}
			hash, err := imagehash.Raw(rr, [2]int{10, 10})
			if err != nil {
				t.Fatal(err)
			}
			if hash != c.Hash {
				t.Errorf("hash got %s want original %s", hash, c.Hash)
			}
		})
	}
}

func TestLegacyAdmissionPrecedesPixels(t *testing.T) {
	var rows []struct{ Name, Encoded string }
	var cases []map[string]json.RawMessage
	if err := json.Unmarshal([]byte(sourceCases), &cases); err != nil {
		t.Fatal(err)
	}
	for _, c := range cases {
		var row struct {
			Name    string
			Encoded string `json:"encoded_base64"`
		}
		b, _ := json.Marshal(c)
		if err := json.Unmarshal(b, &row); err != nil {
			t.Fatal(err)
		}
		rows = append(rows, struct{ Name, Encoded string }{row.Name, row.Encoded})
	}
	rejected := errors.New("owned dimension rejection")
	for _, c := range rows {
		t.Run(c.Name, func(t *testing.T) {
			b, _ := base64.StdEncoding.DecodeString(c.Encoded)
			r, ok, err := legacycodec.Decode(b, func(w, h int) error { return rejected })
			if !ok || err != rejected || r.Pixels != nil {
				t.Fatalf("dimension guard got recognized=%v err=%v output=%d", ok, err, len(r.Pixels))
			}
		})
	}
}
